import{_ as i,o as t,c as o,ag as a}from"./chunks/framework.BpFM782D.js";const u=JSON.parse('{"title":"ecc-code-review","description":"","frontmatter":{},"headers":[],"relativePath":"commands/ecc-ecc-code-review.md","filePath":"commands/ecc-ecc-code-review.md"}'),l={name:"commands/ecc-ecc-code-review.md"};function c(r,e,d,n,s,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="ecc-code-review" tabindex="-1">ecc-code-review <a class="header-anchor" href="#ecc-code-review" aria-label="Permalink to &quot;ecc-code-review&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>ecc-code-review</td></tr><tr><td>說明</td><td>對未提交的變更進行全面的安全與品質審查。呼叫 ecc-code-reviewer agent。</td></tr><tr><td>系列</td><td>ECC</td></tr><tr><td>來源檔案</td><td><code>commands/ecc-code-review.md</code></td></tr></tbody></table><hr><h1 id="code-review" tabindex="-1">Code Review <a class="header-anchor" href="#code-review" aria-label="Permalink to &quot;Code Review&quot;">​</a></h1><p>This command invokes the <strong>ecc-code-reviewer</strong> agent to perform a comprehensive security and quality review of uncommitted changes.</p><h2 id="what-this-command-does" tabindex="-1">What This Command Does <a class="header-anchor" href="#what-this-command-does" aria-label="Permalink to &quot;What This Command Does&quot;">​</a></h2><ol><li><p>Get changed files: git diff --name-only HEAD</p></li><li><p>For each changed file, check for:</p></li></ol><p><strong>Security Issues (CRITICAL):</strong></p><ul><li>Hardcoded credentials, API keys, tokens</li><li>SQL injection vulnerabilities</li><li>XSS vulnerabilities</li><li>Missing input validation</li><li>Insecure dependencies</li><li>Path traversal risks</li></ul><p><strong>Code Quality (HIGH):</strong></p><ul><li>Functions &gt; 50 lines</li><li>Files &gt; 800 lines</li><li>Nesting depth &gt; 4 levels</li><li>Missing error handling</li><li>console.log statements</li><li>TODO/FIXME comments</li><li>Missing JSDoc for public APIs</li></ul><p><strong>Best Practices (MEDIUM):</strong></p><ul><li>Mutation patterns (use immutable instead)</li><li>Emoji usage in code/comments</li><li>Missing tests for new code</li><li>Accessibility issues (a11y)</li></ul><ol start="3"><li><p>Generate report with:</p><ul><li>Severity: CRITICAL, HIGH, MEDIUM, LOW</li><li>File location and line numbers</li><li>Issue description</li><li>Suggested fix</li></ul></li><li><p>Block commit if CRITICAL or HIGH issues found</p></li></ol><p>Never approve code with security vulnerabilities!</p><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><p>Use <code>/ecc-code-review</code> when:</p><ul><li>After writing or modifying code</li><li>Before creating a commit</li><li>Before opening a merge request</li><li>After completing a feature implementation</li></ul><h2 id="integration-with-other-commands" tabindex="-1">Integration with Other Commands <a class="header-anchor" href="#integration-with-other-commands" aria-label="Permalink to &quot;Integration with Other Commands&quot;">​</a></h2><ul><li>Use <code>/ecc-plan</code> to plan before implementation</li><li>Use <code>/ecc-tdd</code> for test-driven development</li><li>Use <code>/ecc-build-fix</code> if build errors occur during review</li><li>Use <code>/ecc-security-review</code> for deeper security analysis</li></ul><h2 id="related-agents" tabindex="-1">Related Agents <a class="header-anchor" href="#related-agents" aria-label="Permalink to &quot;Related Agents&quot;">​</a></h2><p>This command invokes the <code>ecc-code-reviewer</code> agent located at: <code>~/.claude/agents/ecc-code-reviewer.md</code></p>',22)])])}const p=i(l,[["render",c]]);export{u as __pageData,p as default};
